#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.assign(n, 0);
    if (n == 0) return;

    // Parallelize by blocks: each thread handles a contiguous chunk.
    // Phase 1: compute per-block sums and within-block reverse prefix sums (local).
    // Phase 2: compute suffix sums of block sums and add appropriate offset to each block.
    const int T = omp_get_max_threads();
    std::vector<long long> blockSum(T, 0LL);
    std::vector<long long> blockSuffix(T + 1, 0LL);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int numt = omp_get_num_threads();

        // Static block partition (contiguous) based on actual num threads.
        const int chunk = (n + numt - 1) / numt;
        const int start = tid * chunk;
        int end = start + chunk;
        if (end > n) end = n;

        long long localTotal = 0;
        if (start < end) {
            // Sum this block
            for (int i = start; i < end; ++i) localTotal += x[i];

            // Compute reverse prefix sums within the block:
            // output[i] = sum_{k=start..i} x[k] for i in [start,end)
            // but reversed globally we want sum of suffix i..n-1.
            // We'll fix with an offset in phase 2.
            long long run = 0;
            for (int i = start; i < end; ++i) {
                run += x[i];
                output[i] = static_cast<int>(run);
            }
        }
        blockSum[tid] = localTotal;

        #pragma omp barrier

        // Single thread builds block suffix offsets:
        // offset for block tid is sum of all blocks after tid.
        #pragma omp single
        {
            blockSuffix[numt] = 0LL;
            for (int t = numt - 1; t >= 0; --t) {
                blockSuffix[t] = blockSuffix[t + 1] + blockSum[t];
            }
        }

        #pragma omp barrier

        if (start < end) {
            const long long offset = blockSuffix[tid + 1]; // sum of all elements after this block
            // We computed forward prefix within block; reverse prefix (suffix) needs:
            // output[i] = (sum within block from i..end-1) + (sum after block)
            // Convert using: sum_i_to_end = blockTotal - prefixUpTo(i-1)
            // We have prefixUpTo(i) in output[i] currently. Use that to derive sum_i_to_end.
            const long long blockTotal = blockSum[tid];
            long long prefixPrev = 0;
            for (int i = start; i < end; ++i) {
                const long long prefixUpToI = static_cast<long long>(output[i]);
                const long long sumIToEnd = blockTotal - prefixPrev;
                output[i] = static_cast<int>(sumIToEnd + offset);
                prefixPrev = prefixUpToI;
            }
        }
    }
}
